function imgbbReceipt(response) {
  const item = response?.data;
  const size = Number(item?.size);
  if (
    response?.success !== true ||
    response.status !== 200 ||
    typeof item?.id !== "string" ||
    !/^[A-Za-z0-9_-]+$/.test(item.id) ||
    typeof item.url !== "string" ||
    !/^https:\/\/i\.ibb\.co\/[A-Za-z0-9_-]+\/[A-Za-z0-9_%.~-]+$/i.test(item.url) ||
    !Number.isSafeInteger(size) ||
    size < 1
  ) {
    throw new Error("ImgBB did not confirm an uploaded image with a direct HTTPS URL");
  }
  return { url: item.url, size };
}

export default ({ response }) => {
  const original = imgbbReceipt(response);
  return { original, url: original.url };
};

