export default ({ requestedId, resultId, file, sizes }) => {
  if (
    resultId !== requestedId ||
    file?.mimeType !== "image/png" ||
    file.sizeBytes !== sizes.optimizedBytes ||
    typeof file.downloadUrl !== "string" ||
    !/^https:\/\/[^\s/?#@]+\//i.test(file.downloadUrl)
  ) {
    throw new Error("TinyPNG did not return the expected downloadable image");
  }
  return { url: file.downloadUrl };
};

