function checkBytes({ bytes, mime, outputMime, expectedSize }) {
  const at = (offset, length) => Array.from(bytes.subarray(offset, offset + length));
  const ascii = (offset, length) => String.fromCharCode(...at(offset, length));
  const signature = (expected) => expected.every((value, index) => bytes[index] === value);
  const headers = {
    "image/png": () => signature([137, 80, 78, 71, 13, 10, 26, 10]),
    "image/jpeg": () => signature([255, 216, 255]),
    "image/webp": () => ascii(0, 4) === "RIFF" && ascii(8, 4) === "WEBP",
    "image/avif": () => ascii(4, 4) === "ftyp" && ["avif", "avis"].includes(ascii(8, 4)),
    "image/jxl": () =>
      signature([255, 10]) || signature([0, 0, 0, 12, 74, 88, 76, 32, 13, 10, 135, 10]),
  };
  if (
    String(mime ?? "")
      .split(";")[0]
      .toLowerCase() !== outputMime ||
    bytes.length !== expectedSize ||
    !headers[outputMime]?.()
  ) {
    throw new Error("Tinify did not return the complete expected image");
  }
}

export default async ({ response, sizes }, context) => {
  const bytes = await context.artifact.open(response);
  checkBytes({
    bytes,
    mime: response.mediaType,
    outputMime: "image/png",
    expectedSize: sizes.optimizedBytes,
  });
  return {
    file: await context.artifact.put(bytes, { name: "optimized.png", mediaType: "image/png" }),
  };
};

