    size < 1
  ) {
    throw new Error("ImgBB did not confirm an uploaded image with a direct HTTPS URL");
  }
  return { url: item.url, size };
}

export default ({ response, sizes }) => {
  const hosted = imgbbReceipt(response);
  if (hosted.size !== sizes.optimizedBytes)
    throw new Error("ImgBB did not confirm the expected optimized file size");
  return {
    originalUrl: sizes.originalUrl,
    optimizedUrl: hosted.url,
    originalBytes: sizes.originalBytes,
    optimizedBytes: hosted.size,
  };
};
